// يحوّل جسم الـ Webhook إلى نفس شكل مخرجات Form Trigger القديمة (حتى لا تتغير باقي العقد)
const w = $('Webhook').first();
const u = $('Verify User').first().json;
return [{ json: { ...(w.json.body || {}), user_id: u.id, user_email: u.email }, binary: w.binary }];

